package com.lifeos.projects;import com.lifeos.projects.dto.*;import com.lifeos.shared.exception.*;import com.lifeos.users.*;import org.springframework.stereotype.Service;import java.util.*;@Service public class ProjectService{private final ProjectRepository r;private final UserRepository u;public ProjectService(ProjectRepository r,UserRepository u){this.r=r;this.u=u;}private User user(String e){return u.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("User not found"));}private Project owned(Long id,String e){return r.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResourceNotFoundException("Project not found"));}public List<ProjectResponse>list(String e){return r.findAllByUserIdOrderByCreatedAtDesc(user(e).getId()).stream().map(ProjectResponse::from).toList();}public ProjectResponse get(Long i,String e){return ProjectResponse.from(owned(i,e));}public ProjectResponse create(ProjectRequest q,String e){Project p=new Project();p.setUser(user(e));apply(p,q);return ProjectResponse.from(r.save(p));}public ProjectResponse update(Long i,ProjectRequest q,String e){Project p=owned(i,e);apply(p,q);return ProjectResponse.from(r.save(p));}public void delete(Long i,String e){r.delete(owned(i,e));}private void apply(Project p,ProjectRequest q){if(q.startDate()!=null&&q.targetDate()!=null&&q.targetDate().isBefore(q.startDate()))throw new BadRequestException("targetDate cannot be before startDate");p.setName(q.name().trim());p.setDescription(q.description());p.setStatus(q.status());p.setStartDate(q.startDate());p.setTargetDate(q.targetDate());}}
